 const fakePerf={performance:{now:()=>state.performance},monitorEventLoopDelay:()=>({enable(){},reset(){},percentile:()=>1000000})};
 const transport={createClient(options){const gate=deferred(),handlers={};const c={options,handlers,gate,on(event,cb){handlers[event]=cb;return this;},connect(){return gate.promise;},get:async()=>null,isOpen:false,isReady:false};state.created.push(c);return c;}};
