 const sandbox=vm.createContext({process:mockProcess,console:{log:(...x)=>state.logs.push(x.map(String)),error:(...x)=>state.errors.push(x.map(String))},Date:FixedDate,Buffer,URL,Math,setInterval:(cb,ms)=>{const t={cb,ms,unref(){}};state.intervals.push(t);return t;},clearInterval:()=>{},setTimeout:()=>({unref(){}}),clearTimeout:()=>{}});
