function selected(r){return {clients:r.state.created.length,intervals:r.state.intervals.length,intervalMs:r.state.intervals.map(t=>t.ms),metric:Array.from(r.tel.telemetryTesting.snapshot().metrics,m=>({kind:m.kind,name:m.name,outcome:m.outcome,count:m.count,sum:m.sum}))};}
